)

const achievementUnit = computed(() =>
	ratioPct(card2.value.realisasi_unit, card2.value.target_unit, card2.value.achievement_pct),
)
const ringOffset = computed(() => RING - (RING * clampPct(achievementUnit.value)) / 100)

// Tiga kartu berpola sama: satu keseluruhan, lalu porsi tiap sisinya.
const komposisiCards = computed(() => [
	{
		key: 'approval',
