])

// Ketiga skenario, urut & berlabel rumus sama dengan desk. Nilainya datang utuh
// dari endpoint yang sama, tidak dihitung ulang di sini.
const proyeksiRows = computed(() => {
	const p = proyeksi.value
	const sisi = p?.[proyeksiMode.value]
	if (!sisi) return []
	const lama = sisi.formula_lama || {}
	const s3 = sisi.skenario_3 || {}
	const s1 = sisi.skenario_1 || {}
	const beta = p.beta_pct != null ? `${p.beta_pct}%` : 'β'
	const sisaHari = { label: 'Sisa hari kerja', value: `${int(p.sisa_hari)} hari` }
	return [
		{
			key: 'formula_lama',
