			vs_target_pct: lama.vs_target_pct,
			detail: [
				{ label: 'Rata-rata/hari', value: nilaiProyeksi(lama.rata_per_hari) },
				sisaHari,
			],
		},
		{
			key: 'skenario_3',
			nama: 'Skenario 3 · Pelaporan',
			formula: '(R ÷ HB)×HT + P×(1−β)',
			color: '#3B6D11',
			nilai: s3.nilai,
			vs_target_pct: s3.vs_target_pct,
			detail: [
				{ label: 'Proyeksi organik', value: nilaiProyeksi(s3.proyeksi_organik) },
				{
					label: `Kontribusi pending (β ${beta})`,
					value: `+${nilaiProyeksi(s3.kontribusi_pending)}`,
					color: '#3B6D11',
				},
			],
		},
		{
			key: 'skenario_1',
			nama: 'Skenario 1 · Operasional',
			formula: '[(R + P×(1−β)) ÷ HB] × HT',
			color: '#185FA5',
			nilai: s1.nilai,
			vs_target_pct: s1.vs_target_pct,
			detail: [
				{ label: 'Rata-rata/hari', value: nilaiProyeksi(s1.rata_per_hari) },
				sisaHari,
			],
		},
	]
})

// Chart: target CMO satu angka untuk semua bulan, jadi batang targetnya sama
// tinggi sepanjang tahun. Mode amount tidak punya target sehingga hanya satu batang.
const chartMonths = computed(() => {
	const c = dash.value?.charts?.actual_vs_target || {}
	const target = Number(c.target_unit) || 0
	return (c.months || []).map((m) => {
		const unit = Number(m.realisasi_unit) || 0
		if (chartMode.value === 'amount') {
			return {
				label: m.label,
				nilai: Number(m.realisasi) || 0,
				target: 0,
				atas: rupiahRingkas(m.realisasi),
			}
		}
		return {
			label: m.label,
			nilai: unit,
			target,
			atas: target ? pct((unit / target) * 100) : '—',
		}
	})
})
const chartMax = computed(() =>
	Math.max(1, ...chartMonths.value.flatMap((m) => [m.nilai, m.target])),
)

// ---- Format ----------------------------------------------------------------
function int(value) {
	if (value === null || value === undefined) return '—'
	return fmtNum(value, 0)
}

function rupiahFull(value) {
	if (value === null || value === undefined) return '—'
	const n = Number(value) || 0
	return `${n < 0 ? '-' : ''}Rp ${fmtNum(Math.abs(n), 0)}`
}

function rupiahRingkas(value) {
	if (value === null || value === undefined) return '—'
	const n = Number(value) || 0
	const abs = Math.abs(n)
	const sign = n < 0 ? '-' : ''
	if (abs >= 1e12) return `${sign}Rp ${fmtNum(abs / 1e12, 2)} T`
	if (abs >= 1e9) return `${sign}Rp ${fmtNum(abs / 1e9, 2)} M`
	if (abs >= 1e6) return `${sign}Rp ${fmtNum(abs / 1e6, 2)} Jt`
	if (abs >= 1e3) return `${sign}Rp ${fmtNum(abs / 1e3, 2)} rb`
	return `${sign}Rp ${fmtNum(abs, 0)}`
}

/** Nilai proyeksi mengikuti mode yang sedang dilihat: rupiah atau unit. */
function nilaiProyeksi(value) {
	if (value === null || value === undefined) return '—'
	return proyeksiMode.value === 'amount' ? rupiahFull(value) : `${int(value)} unit`
}

function pct(value) {
	if (value === null || value === undefined) return 'n/a'
	return `${fmtNumFixed(value, 2)}%`
}

function delta(value) {
	if (value === null || value === undefined) return 'n/a'
	const n = Number(value)
	if (!Number.isFinite(n)) return 'n/a'
	return `${n > 0 ? '+' : ''}${fmtNumFixed(n, 2)}%`
}

/**
 * Persentase dari dua angka mentahnya. Server membulatkan sebagian persentase
 * ke 1 desimal; menghitung ulang membuat dua desimalnya benar-benar berarti.
 */
function ratioPct(num, den, fallback = null) {
	const d = Number(den) || 0
	if (!d) return fallback ?? null
	return ((Number(num) || 0) / d) * 100
}

function sharePct(value, total) {
	const t = Number(total) || 0
	if (!t) return 0
	return (Math.max(0, Number(value) || 0) / t) * 100
}

function barHeight(value, max) {
	const v = Math.max(0, Number(value) || 0)
	return `${Math.min(100, (v / max) * 100)}%`
}

function deltaPillClass(value) {
	const n = Number(value)
	if (!Number.isFinite(n)) return 'bg-ui-surface-gray-100 text-ui-ink-gray-500'
	return n >= 0
		? 'bg-ui-surface-green-50 text-ui-ink-green-600'
		: 'bg-ui-surface-red-50 text-ui-ink-red-600'
}

// ---- Aksi ------------------------------------------------------------------
function openFilter() {
	Object.assign(draft, filters)
	showFilter.value = true
}

function resetFilter() {
	draft.bulan = now.getMonth() + 1
	draft.tahun = now.getFullYear()
}

function applyFilter() {
	filters.bulan = draft.bulan
	filters.tahun = draft.tahun
	if (filters.bulan === now.getMonth() + 1 && filters.tahun === now.getFullYear()) {
		listPersistence.clearSession()
	} else {
		listPersistence.writeSession({ filters })
	}
	showFilter.value = false
	loadAll()
}

async function selectTab(key) {
	if (tab.value === key) return
	tab.value = key
	loadingTab.value = true
	try {
		await loadDemografi()
	} finally {
		loadingTab.value = false
	}
}

async function loadDemografi() {
	const args = { bulan: filters.bulan, tahun: filters.tahun }
	try {
		if (tab.value === 'audience') {
			audience.value = await call(API_AUDIENCE, args)
			return
		}
		demografi.value = await call(API_DEMOGRAPHICS, { ...args, dimension: tab.value })
	} catch (e) {
		notifyError(e, 'Gagal memuat demografi')
	}
}

// Proyeksi WAJIB dipanggil setelah bundel: R (realisasi berjalan) adalah masukan
// rumusnya dan tidak dihitung sendiri oleh endpointnya.
async function loadProyeksi() {
	try {
		proyeksi.value = await call(API_PROYEKSI, {
			bulan: filters.bulan,
			tahun: filters.tahun,
			realisasi_amount: Number(card1.value.realisasi_amount) || 0,
			realisasi_unit: Number(card2.value.realisasi_unit) || 0,
		})
	} catch {
		proyeksi.value = null
	}
}

async function loadAll() {
	loading.value = true
	try {
		dash.value = await call(API_DASHBOARD, { bulan: filters.bulan, tahun: filters.tahun })
		fatalError.value = ''
		loadProyeksi()
		await loadDemografi()
	} catch (e) {
		if (!dash.value) fatalError.value = errorText(e)
		else notifyError(e, 'Gagal memuat CMO Sales Dashboard')
	} finally {
		loading.value = false
	}
}

async function reload() {
	if (loading.value) return
	await loadAll()
}

// Pesan Frappe datang sebagai `messages` (list HTML) atau `message`.
function errorText(e) {
	const raw = e?.messages?.join(' ') || e?.message || ''
	const text = String(raw)
		.replace(/<[^>]*>/g, ' ')
		.replace(/\s+/g, ' ')
		.trim()
	return text || 'Anda tidak punya akses ke dashboard ini.'
}

onMounted(async () => {
	await refreshCsrfToken()
	const saved = listPersistence.readSession({
		filters: { bulan: now.getMonth() + 1, tahun: now.getFullYear() },
	}).filters
	if (saved.bulan >= 1 && saved.bulan <= 12) filters.bulan = saved.bulan
	if (saved.tahun >= 2000 && saved.tahun <= now.getFullYear() + 1) filters.tahun = saved.tahun
	await loadAll()
})
</script>
